import "core-js/modules/es.array.push.js";
import GoogleMaps from "@/components/GoogleMaps.vue";
export default {
  components: {
    GoogleMaps
  },
  props: {
    viewSwipeLocation: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      center: {
        lat: 45.508,
        lng: -73.587
      },
      markers: [],
      places: [],
      currentPlace: null,
      mapCenter: {
        lat: 45.508,
        lng: -73.587
      },
      mapMarkers: []
    };
  },
  watch: {
    viewSwipeLocation: {
      async handler() {
        if (this.viewSwipeLocation == true) {
          if (this.rowInfo.swipe_lat != null && this.rowInfo.swipe_long != null) {
            this.markers = [];
            var marker = {
              position: {
                lat: Number(this.rowInfo.swipe_lat),
                lng: Number(this.rowInfo.swipe_long)
              }
            };
            this.markers.push(marker);
            this.mapMarkers = this.markers;
            this.mapCenter = marker.position;
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    onMapsLoaded() {
      // console.log("Google Maps loaded successfully");
    },
    onMarkerClick(marker) {
      this.mapCenter = marker.position;
    }
  }
};
